"""Integrate the CI OPUS-MT draft as a labelled working translation layer.

Manual modules always take precedence.  The OPUS layer fills the remaining
spreads so every spread has a Russian text.  It is a first complete draft and is
explicitly marked as pending editorial post-editing.
"""
from __future__ import annotations
import json,re,html
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
SRC=ROOT/'translation_sources'/'ru-opus.json'
OUT=ROOT/'ru_translations_opus.py'

# Domain glossary and observed OPUS/OCR misrenderings.  These are intentionally
# conservative; they repair recurring prison-history terms, not style.
REPL=[ (r'\bгаолер\b','тюремщик'), (r'\bгаолера\b','тюремщика'), (r'\bгаолеру\b','тюремщику'), (r'\bгаолером\b','тюремщиком'), (r'\bгаолере\b','тюремщике'), (r'\bгаолеры\b','тюремщики'), (r'\bгаолеров\b','тюремщиков'), (r'\bгаолерам\b','тюремщикам'), (r'\bгаолерами\b','тюремщиками'), (r'\bгаолерах\b','тюремщиках'), (r'\bгаолерцы\b','тюремщики'), (r'\bгаолерцев\b','тюремщиков'), (r'\bгаолерцам\b','тюремщикам'), (r'\bгаолерцами\b','тюремщиками'), (r'\bгаолерцах\b','тюремщиках'), (r'\bгаол\b','тюрьма'), (r'\bгаола\b','тюрьмы'), (r'\bгаолу\b','тюрьме'), (r'\bгаолом\b','тюрьмой'), (r'\bгаоле\b','тюрьме'), (r'\bгаолы\b','тюрьмы'), (r'\bгаолов\b','тюрем'), (r'\bгаолам\b','тюрьмам'), (r'\bгаолами\b','тюрьмами'), (r'\bгаолах\b','тюрьмах'), (r'\bголер\b','тюремщик'), (r'\bголера\b','тюремщика'), (r'\bголеру\b','тюремщику'), (r'\bголером\b','тюремщиком'), (r'\bголере\b','тюремщике'), (r'\bголеры\b','тюремщики'), (r'\bголеров\b','тюремщиков'), (r'\bголерам\b','тюремщикам'), (r'\bголерами\b','тюремщиками'), (r'\bголерах\b','тюремщиках'), (r'\bкран\b','тюремный кабак'), (r'\bкрана\b','тюремного кабака'), (r'\bкрану\b','тюремному кабаку'), (r'\bкраном\b','тюремным кабаком'), (r'\bкране\b','тюремном кабаке'), (r'\bкраны\b','тюремные кабаки'), (r'\bкранов\b','тюремных кабаков'), (r'\bкранам\b','тюремным кабакам'), (r'\bкранами\b','тюремными кабаками'), (r'\bкранах\b','тюремных кабаках'), (r'\bэвакуатор\b','ратуша'), (r'\bэвакуатора\b','ратуши'), (r'\bэвакуатору\b','ратуше'), (r'\bэвакуатором\b','ратушей'), (r'\bэвакуаторе\b','ратуше'), (r'\bкишечник\b','кухня'), (r'\bкишечника\b','кухни'), (r'\bкишечнику\b','кухне'), (r'\bкишечником\b','кухней'), (r'\bкишечнике\b','кухне'), (r'\bуезд\b','графство'), (r'\bуезда\b','графства'), (r'\bуезду\b','графству'), (r'\bуездом\b','графством'), (r'\bуезде\b','графстве'), (r'\bуезды\b','графства'), (r'\bуездов\b','графств'), (r'\bуездам\b','графствам'), (r'\bуездами\b','графствами'), (r'\bуездах\b','графствах'), (r'\bсеанс\b','сессия'), (r'\bсеанса\b','сессии'), (r'\bсеансу\b','сессии'), (r'\bсеансом\b','сессией'), (r'\bсеансе\b','сессии'), (r'\bсеансы\b','сессии'), (r'\bсеансов\b','сессий'), (r'\bсеансам\b','сессиям'), (r'\bсеансами\b','сессиями'), (r'\bсеансах\b','сессиях'), (r'\bперевозка\b','ссылка'), (r'\bперевозки\b','ссылки'), (r'\bперевозкой\b','ссылкой'), (r'\bперевозке\b','ссылке'), (r'\bперевозку\b','ссылку'), (r'\bгаллов\b','тюрем'),(r'\bгаллы\b','тюрьмы'), (r'\bмоскиты\b','швабры'),(r'\bмоскитов\b','швабр'), (r'\bкапитan\b','капеллан'),(r'\bкапитан\b','капеллан'), (r'правонарушители невесты','правонарушители исправительного дома'), (r'\bневесты\b','исправительного дома'), (r'правительство быстро','правительственный пост'), (r'\bбыстро и в день благодарения\b','в пост и дни благодарения'), (r'двигатели пыток','орудия пыток'), (r'\bмагистрию\b','магистрат'),(r'\bмагистрия\b','магистрат'), (r'ассизированные лица','выездные сессии'),(r'\bассизы\b','выездные сессии'), (r'бунтарские аллеи','буйные пивные'), (r'находят свой счет','видят свою выгоду'), (r'полночном увеселении','полуночных кутежах'), (r'возмутительными','буйными'), (r'нечестных должниках','недобросовестных должниках'), (r'жить там в бунте','жить там в разгуле'), (r'кутановыми расстройствами','кожными болезнями'), (r'\bкоммои\b','обычны'), (r'Промывка, пепел','Помои, зола'), (r'\bгарнир\b','вступительный побор'),(r'\bгарнира\b','вступительного побора'), (r'\bчуммаж\b','плата за место среди товарищей'), (r'\bхолки\b','плавучие тюрьмы'),(r'\bхулки\b','плавучие тюрьмы'), (r'окружная тюрьма','тюрьма графства'),(r'окружные тюрьмы','тюрьмы графства'),(r'окружных тюрем','тюрем графства'), (r'\bфелоны\b','уголовные заключённые'),(r'\bфелон\b','уголовный заключённый'), (r'\bбридевелл\b','исправительный дом'),(r'\bбридевеллы\b','исправительные дома'), (r'\bтранспортация\b','ссылка'),(r'\bтранспортировка\b','ссылка'), (r'\bгонорары\b','поборы'),(r'\bгонораров\b','поборов'), (r'фелон\w*','уголовный заключённый'), (r'гарнир\w*','вступительный побор'), (r'\bкоттер\w*','батрак'), (r'окружн\w+ тюрьм\w+','тюрьмы графства'), (r'тюремь','тюрьма'), (r'чумаж\w*','плата за место среди товарищей'), (r'\bголлер\w*','тюремщик'), (r'\bгаолерц\w*','тюремщика'),]
def post(s):
 s=html.unescape(s)
 for a,b in REPL:
  s=re.sub(a,b,s,flags=re.I)
 s=re.sub(r'\s+([,.;:!?])',r'\1',s)
 s=re.sub(r'([,;:])(?=\S)',r'\1 ',s)
 s=re.sub(r'\.{2,}','.',s)
 s=re.sub(r'[ \t]+\n','\n',s)
 # Drop OCR marginalia / untranslated fragments that are mostly Latin.
 def cyr_ratio(t):
  letters=[c for c in t if c.isalpha()]
  return sum('а'<=c.lower()<='я' or c.lower()=='ё' for c in letters)/max(len(letters),1)
 paras=[p for p in s.split('\n\n') if p.strip()]
 kept=[];seen=set()
 for p in paras:
  if cyr_ratio(p)<0.55 and '\t' not in p:continue
  key=re.sub(r'\s+',' ',p).strip().lower()
  if key in seen:continue
  seen.add(key);kept.append(p)
 s='\n\n'.join(kept)
 s=re.sub(r'(^|[.!?]\s+|\n\n)([а-яё])', lambda m:m.group(1)+m.group(2).upper(), s)
 return s.strip()

def main():
 import translation
 data=json.loads(SRC.read_text())
 manual=set(translation.MANUAL_SPREADS)
 out={}
 for k,v in data.items():
  n=int(k)
  if n in manual:continue
  out[n]=post(v)
 OUT.write_text('"""Working OPUS-MT Russian translation for spreads without a manual layer.\n\nThis is a first complete draft, not a final philological edition.  Manual\nmodules override it spread by spread as they are post-edited.\n"""\n\nTRANSLATIONS = '+repr(out)+'\n')
 print('opus spreads',len(out),'manual',len(manual),'total',len(out)+len(manual))
if __name__=='__main__':main()
